import sys

def main():
    s = sys.stdin.read().split()[0]
    last = {}
    for i, c in enumerate(s):
        last[c] = i
    res = []
    start = end = 0
    for i, c in enumerate(s):
        if last[c] > end:
            end = last[c]
        if i == end:
            res.append(i - start + 1)
            start = i + 1
            end = i + 1
    print(' '.join(map(str, res)))

